mapper.update:
update mall_flash_sale
title = #{title}, flash_price = #{flashPrice}, stock_limit = #{stockLimit}, per_limit = #{perLimit}, start_time = #{startTime}, end_time = #{endTime}, status = #{status},
where sale_id = #{saleId}

update mall_flash_sale
set sold_count = sold_count + #{quantity}
where sale_id = #{saleId}
  and sold_count + #{quantity} <= stock_limit
